<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Config;final class MaterialStorage{public static function path(array$file):string{return Config::storage().'/files/'.$file['storage_key'];}public static function available(array$file):bool{$path=self::path($file);clearstatcache(true,$path);if(!is_file($path)||is_link($path)||@filesize($path)!==(int)$file['size_bytes'])return false;$stream=@fopen($path,'rb');if(!$stream)return false;fclose($stream);return true;}public static function matches(string$path,array$file):bool{clearstatcache(true,$path);if(!is_file($path)||is_link($path)||@filesize($path)!==(int)$file['size_bytes'])return false;$hash=@hash_file('sha256',$path);return is_string($hash)&&hash_equals($file['checksum_sha256'],$hash);}}